#!/usr/bin/env python3
"""Regenerate public dependency locks from ``deps.json``.

The public checkout has no access to the internal ``rtpcli`` package.  This small
maintainer tool keeps the public relock path self-contained: the manifest is
composed in a temporary directory, ``uv pip compile`` resolves one profile, and
the generated lock plus ``absent_map.bzl`` are replaced atomically.
"""

import argparse
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile
import time
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

HERE = os.path.dirname(os.path.abspath(__file__))

# Loaded by importlib from a [file path] (this is how internal-source tests pin the lock
# header against rtpcli/deps_sync.py); sys.path then lacks deps/, so the sibling modules
# below cannot be imported. Direct execution and py_binary never had this problem.
if HERE not in sys.path:
    sys.path.insert(0, HERE)

from compose import (
    ALIYUN_INDEX,
    SRC_NAME,
    absent_digest,
    canonical_resolution_argv,
    composed_inputs,
    resolution_digest,
)
from pkgname import norm

DEPS = Path(__file__).resolve().parent
OSS_HOST = "https://{bucket}.oss-cn-hangzhou.aliyuncs.com/rtp_llm"
LOCK_HEADER = (
    "# This file is autogenerated by `scripts/rtpcli deps sync` "
    "(uv, constraint-pinned relock). DO NOT EDIT."
)
ABSENT_HEADER = (
    "# GENERATED by deps/relock.py from `exceptions` in deps.json. DO NOT EDIT.\n"
    "# To change the dependency-absence registry, edit `exceptions[].exists_in` in deps.json and rerun `scripts/rtpcli deps sync --all`;\n"
    "# consumed by requirement() in arch_config/arch_select.bzl (absent branches route to the absent_dep stub, an explicit analysis-time failure)."
)
TRANSIENT = re.compile(
    r"Failed to fetch|40[39] Forbidden|429|Too Many Requests|"
    r"Connection (?:reset|refused|closed)|timed? ?out|Temporary failure|"
    r"Network is unreachable",
    re.I,
)


def _profile(manifest, name):
    for profile in manifest["profiles"]:
        if profile["name"] == name:
            return profile
    raise ValueError("unknown public profile %r" % name)


def _constraints(lock_text, base, source):
    """Keep prior pins, except direct pins no longer satisfying the new inputs."""
    try:
        from packaging.requirements import InvalidRequirement, Requirement
        from packaging.utils import canonicalize_name
        from packaging.version import InvalidVersion, Version
    except ImportError:
        try:
            from pip._vendor.packaging.requirements import (
                InvalidRequirement,
                Requirement,
            )
            from pip._vendor.packaging.utils import canonicalize_name
            from pip._vendor.packaging.version import InvalidVersion, Version
        except ImportError as exc:
            raise RuntimeError(
                "relock needs packaging; install it with `%s -m pip install packaging`"
                % sys.executable
            ) from exc

    specs = {}
    for content in (base, source):
        for raw in content.splitlines():
            line = raw.split("#", 1)[0].strip()
            if not line or line.startswith("-r ") or line.startswith("-r\t"):
                continue
            try:
                requirement = Requirement(line)
            except InvalidRequirement:
                continue
            specs.setdefault(canonicalize_name(requirement.name), []).append(
                requirement.specifier
            )

    result = []
    # Keep this pin regex identical to deps_sync.build_constraint: the two lock
    # producers must keep/release the same prior pins or their bytes drift.
    pin_re = re.compile(r"^([A-Za-z0-9._-]+)==([^ ;\\]+)")
    for raw in lock_text.splitlines():
        match = pin_re.match(raw)
        if not match:
            continue
        name, version = match.groups()
        keep = True
        for specifier in specs.get(canonicalize_name(name), []):
            try:
                keep = keep and specifier.contains(Version(version), prereleases=True)
            except InvalidVersion:
                keep = False
        if keep:
            result.append("%s==%s" % (name, version))
    return "\n".join(result) + "\n" if result else ""


def _require_pinned_uv(manifest):
    """Running uv must be the pinned one: its `# via` annotation formatting is
    version-dependent, so a different uv rewrites those comment lines and every committed
    lock reads as DRIFT with nothing in the repo having changed."""
    want = manifest.get("python", {}).get("uv")
    if not want:
        return
    try:
        out = subprocess.run(
            ["uv", "--version"], stdout=subprocess.PIPE, text=True, check=True
        ).stdout
    except (OSError, subprocess.CalledProcessError) as exc:
        raise RuntimeError(
            "cannot determine uv version (%s); need uv==%s" % (exc, want)
        )
    got = out.split()[1] if len(out.split()) > 1 else out.strip()
    if got != want:
        raise RuntimeError(
            "uv %s != pinned %s (deps.json python.uv). uv's annotation formatting is "
            "version-dependent, so this would rewrite every lock's `# via` lines and "
            "report DRIFT on all profiles. Install the pinned one: "
            "python3 -m pip install -q 'uv==%s'" % (got, want, want)
        )


def _run_uv(argv, cwd):
    for attempt in range(3):
        completed = subprocess.run(
            argv,
            cwd=cwd,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            check=False,
        )
        output = (completed.stdout or "") + (completed.stderr or "")
        if completed.returncode == 0 or not TRANSIENT.search(output) or attempt == 2:
            if completed.returncode != 0:
                tail = "\n".join(output.splitlines()[-30:])
                raise RuntimeError(
                    "uv pip compile failed (rc=%d):\n%s" % (completed.returncode, tail)
                )
            return
        time.sleep(3 * (attempt + 1))


def _generate_lock(manifest, profile_name):
    profile = _profile(manifest, profile_name)
    base, source = composed_inputs(manifest, profile_name)
    lock_path = DEPS / profile["lock"]
    with tempfile.TemporaryDirectory(prefix="rtp-public-relock-") as work:
        workdir = Path(work)
        source_path = workdir / SRC_NAME
        base_path = workdir / "requirements_base.txt"
        output_path = workdir / "generated-lock.txt"
        source_path.write_text(source, encoding="utf-8")
        base_path.write_text(base, encoding="utf-8")

        constraint_path = None
        if lock_path.is_file():
            constraint = _constraints(
                lock_path.read_text(encoding="utf-8"), base, source
            )
            if constraint:
                constraint_path = workdir / "constraint.txt"
                constraint_path.write_text(constraint, encoding="utf-8")

        # The argv is the canonical one from compose (also the fingerprint basis); only
        # the output path becomes a real path and the optional constraint is appended.
        argv = list(canonical_resolution_argv(manifest, profile_name))
        argv[argv.index("-o") + 1] = output_path.name
        if constraint_path is not None:
            argv += ["--constraint", constraint_path.name]
        _run_uv(argv, str(workdir))
        body = output_path.read_text(encoding="utf-8")
        body = (
            "\n".join(
                line
                for line in body.splitlines()
                if not re.match(r"^\s*#\s+-c\s+\S", line)
            )
            + "\n"
        )
    return lock_path, (
        LOCK_HEADER
        + "\n# input-hash: "
        + resolution_digest(
            manifest, profile_name, manifest.get("python", {}).get("uv")
        )
        + "\n"
        + body
    ).encode("utf-8")


def _absent_map(manifest):
    profiles = [p["name"] for p in manifest.get("profiles", [])]
    absent = {}
    reasons = {}
    for exception in manifest.get("exceptions", []):
        key = norm(exception.get("name", ""))
        if not key:
            continue
        exists = {norm(p) for p in exception.get("exists_in", [])}
        missing = [p for p in profiles if norm(p) not in exists]
        if not missing:
            continue
        absent[key] = missing
        reasons[key] = exception.get("reason", "") or "only exists in %s" % ", ".join(
            exception.get("exists_in", [])
        )

    lines = [
        ABSENT_HEADER,
        "# input-hash: " + absent_digest(manifest),
        "",
        "ABSENT = {",
    ]
    lines += [
        '    "%s": [%s],' % (k, ", ".join('"%s"' % p for p in absent[k]))
        for k in sorted(absent)
    ]
    lines += ["}", "", "ABSENT_REASON = {"]
    lines += ['    "%s": "%s",' % (k, reasons[k]) for k in sorted(reasons)]
    lines += ["}", ""]
    return "\n".join(lines).encode("utf-8")


def _replace(path, data):
    path = Path(path)
    temporary = path.with_name(".%s.tmp.%d" % (path.name, os.getpid()))
    temporary.write_bytes(data)
    os.replace(temporary, path)


def main(argv=None):
    parser = argparse.ArgumentParser(
        description="regenerate public deps locks from deps.json"
    )
    group = parser.add_mutually_exclusive_group(required=True)
    group.add_argument(
        "--profile", action="append", help="profile to relock; repeatable"
    )
    group.add_argument("--all", action="store_true", help="relock every public profile")
    parser.add_argument(
        "--check", action="store_true", help="compare generated files without writing"
    )
    args = parser.parse_args(argv)

    manifest = json.loads((DEPS / "deps.json").read_text(encoding="utf-8"))
    _require_pinned_uv(manifest)
    names = [p["name"] for p in manifest["profiles"]] if args.all else args.profile
    uv_pin = manifest.get("python", {}).get("uv")

    # Fingerprint fast path: a committed lock whose `# input-hash:` equals the digest of
    # the CURRENT resolution inputs (generator version, uv argv, uv pin, base+src) was
    # produced by exactly this resolution — no need to spawn uv against the network for
    # it. Only the profiles whose stamps miss get resolved, so an unchanged tree costs
    # milliseconds and a one-dependency change re-resolves one profile, not six.
    stamp_re = re.compile(r"^#\s*input-hash:\s*([0-9a-f]{64})", re.M)
    by_name = {p["name"]: p for p in manifest["profiles"]}
    fresh, pending = [], []
    for name in names:
        lock_path = DEPS / by_name[name]["lock"]
        m = (
            stamp_re.search(lock_path.read_text(encoding="utf-8"))
            if lock_path.is_file()
            else None
        )
        if m and m.group(1) == resolution_digest(manifest, name, uv_pin):
            fresh.append(name)
        else:
            pending.append(name)

    generated = []
    if pending:
        # uv is only needed when something actually needs resolving; a fully-fresh tree
        # checks in milliseconds without it.
        if not shutil.which("uv"):
            parser.error("uv is required (install uv or add it to PATH)")
        _require_pinned_uv(manifest)
        # Each profile resolves in its own tmp workdir and is network-bound; run them
        # in parallel, collecting in profile order for deterministic output.
        with ThreadPoolExecutor(max_workers=min(8, max(1, len(pending)))) as pool:
            generated = list(
                pool.map(lambda name: _generate_lock(manifest, name), pending)
            )
    generated.append((DEPS / "absent_map.bzl", _absent_map(manifest)))
    drift = [
        str(path.relative_to(DEPS))
        for path, data in generated
        if not path.is_file() or path.read_bytes() != data
    ]
    if args.check:
        if drift:
            print("DRIFT: " + ", ".join(drift))
            return 1
        if fresh:
            print(
                "OK: generated public dependency files are current "
                "(%d profile(s) fresh by input-hash, %d resolved)"
                % (len(fresh), len(pending))
            )
        else:
            print("OK: generated public dependency files are current")
        return 0
    for path, data in generated:
        _replace(path, data)
    note = ", ".join(str(path.relative_to(DEPS)) for path, _ in generated) + (
        "" if not fresh else " (skipped %d fresh by input-hash)" % len(fresh)
    )
    print("updated: " + note)
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except (OSError, RuntimeError, ValueError) as exc:
        print("FAIL: %s" % exc, file=sys.stderr)
        raise SystemExit(1)
